def calculate_discount(total: float) -> float:
    """Return the discounted price for an order total."""
    discount = 0.1
    if total > 100:
        discount = 0.2
    # BUG: returns the discount amount applied to total, not the
    # discounted price; should be total * (1 - discount)
    return total * discount


def apply_tax(amount: float, rate: float) -> float:
    return amount + amount * rate
